-- SISTEMA DE BLACK FOG UNIFICADO (BOTÃO + TECLADO)
-- ====================================================================

-- 1. CONFIGURAÇÕES DA NÉVOA
local FOG_COLOR = Color3.fromRGB(0, 0, 0) -- Cor: Preto
local FOG_START = 0                       -- Onde a névoa começa
local FOG_END = 45                        -- Onde a névoa fica totalmente opaca

-- 2. GUARDAR ESTADO ORIGINAL DO MAPA
local originalFogColor = game.Lighting.FogColor
local originalFogStart = game.Lighting.FogStart
local originalFogEnd = game.Lighting.FogEnd

-- 3. VARIÁVEIS DE CONTROLE e SERVIÇOS
local UserInputService = game:GetService("UserInputService")
local botao = script.Parent -- O script precisa estar DENTRO do TextButton/ImageButton
local fogAtivo = false

-- 4. FUNÇÃO PRINCIPAL DE ALTERNÂNCIA (TOGGLE)
local function AlternarBlackFog()
    if not fogAtivo then
        -- Salva o clima original antes de aplicar (se já não for o preto)
        if game.Lighting.FogColor ~= FOG_COLOR then
            originalFogColor = game.Lighting.FogColor
            originalFogStart = game.Lighting.FogStart
            originalFogEnd = game.Lighting.FogEnd
        end
        
        -- Ativa o Black Fog
        game.Lighting.FogColor = FOG_COLOR
        game.Lighting.FogStart = FOG_START
        game.Lighting.FogEnd = FOG_END
        
        -- Atualiza interface e estado
        botao.Text = "Desativar Black Fog"
        fogAtivo = true
    else
        -- Desativa o Black Fog (Restaura o original)
        game.Lighting.FogColor = originalFogColor
        game.Lighting.FogStart = originalFogStart
        game.Lighting.FogEnd = originalFogEnd
        
        -- Atualiza interface e estado
        botao.Text = "Ativar Black Fog"
        fogAtivo = false
    end
end

-- 5. EVENTO DO CLIQUE NO BOTÃO
botao.MouseButton1Click:Connect(AlternarBlackFog)

-- 6. EVENTO DA TECLA NO TECLADO (Tecla F)
UserInputService.InputBegan:Connect(function(input, gameProcessed)
    if gameProcessed then return end -- Ignora se o jogador estiver digitando no chat
    
    if input.KeyCode == Enum.KeyCode.F then -- Altere 'F' para a tecla que preferir
        AlternarBlackFog()
    end
end)
